# Casa secreta (C5b, contract 48), 9 x 7, interior. column = i, row = j. The Reserva's SECRET HOUSE: the host gives the HIDRODESLIZADOR module (flag 90 = `mod_hidro`,
# flag 835 = the gift was given; the module only works with the Medalla Toxina). Whoever reaches the deepest area finds it: a lantern-lit room with a chart of the sea on the wall.
@map casa_secreta
@size 9 7
@interior yes
@bg 3
@fill floor_wood
@spawn door 4 5 N
@flag hidro_given 835
@legend
  .  tile=floor_wood
  a  tile=none object=wall_corner
  b  tile=none object=wall_j
  c  tile=none object=wall_win_j
  d  tile=none object=wall_i
  p  tile=none object=wall_poster_j text=secret.chart interact=look
  e  object=bed
  f  object=bookshelf text=rest.books interact=look
  h  object=table
  i  npc=anciano id=host face=SW script=host
  j  object=candle_s
  l  object=lifebuoy
  k  tile=mat
@grid
  abbcpbcbb
  de..f...l
  de.......
  d..hi....
  d.j......
  d........
  d...kk...
@warp k -> reserva_4 spawn=secret_door
# The host: the HIDRODESLIZADOR at the first talk (the module is a flag), then a last line.
@script host npc
    npc_face_hero host
    jf hidro_given said
    say secret.a
    setf mod_hidro
    sfx item
    say secret.got
    say secret.about
    say secret.about2
    setf hidro_given
    end
  said:
    say secret.after
@end
